B.Y9=new A.X(61326,"MaterialIcons",null,!1)
B.aaZ=new A.aL(B.Y9,"Detaliile bancare sunt colectate de Stripe \u0219i nu sunt stocate pe serverele noastre.")
B.aaO=new A.aL(B.qQ,"Po\u021bi cere oric\xe2nd \u0219tergerea permanent\u0103 a contului \u0219i a datelor asociate.")
